import{_ as e,o,c as t,ag as s}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"features/commands.md","filePath":"features/commands.md"}'),n={name:"features/commands.md"};function i(d,a,l,r,c,m){return o(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><p>Create, manage, and organize custom slash commands for Claude Code.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Slash commands are markdown files that Claude Code executes when you type <code>/command-name</code>. Claude Deck lets you browse all available commands across user, project, and plugin scopes, create new ones with a guided wizard, and edit existing ones.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="browsing-commands" tabindex="-1">Browsing Commands <a class="header-anchor" href="#browsing-commands" aria-label="Permalink to &quot;Browsing Commands&quot;">​</a></h3><p>The Commands page shows all available commands grouped by scope:</p><ul><li><strong>User</strong> — global commands in <code>~/.claude/commands/</code></li><li><strong>Project</strong> — project-specific commands in <code>.claude/commands/</code></li><li><strong>Plugin</strong> — commands provided by installed plugins (read-only)</li></ul><p>Use the search bar to filter by name, description, or content. Stats at the top show counts per scope.</p><h3 id="creating-a-command" tabindex="-1">Creating a Command <a class="header-anchor" href="#creating-a-command" aria-label="Permalink to &quot;Creating a Command&quot;">​</a></h3><p>Click <strong>&quot;Add Command&quot;</strong> to open the wizard:</p><ol><li><strong>Name</strong> — enter the command name and optional namespace (e.g., <code>tools:analyze</code> becomes <code>/tools:analyze</code>)</li><li><strong>Scope</strong> — choose user (global) or project (version-controlled)</li><li><strong>Frontmatter</strong> — add description and allowed tools</li><li><strong>Content</strong> — select a template or write custom markdown</li></ol><h3 id="editing-commands" tabindex="-1">Editing Commands <a class="header-anchor" href="#editing-commands" aria-label="Permalink to &quot;Editing Commands&quot;">​</a></h3><p>Click a command card to view its details, then click <strong>Edit</strong> to modify the description, allowed tools, or markdown content.</p><h3 id="allowed-tools" tabindex="-1">Allowed Tools <a class="header-anchor" href="#allowed-tools" aria-label="Permalink to &quot;Allowed Tools&quot;">​</a></h3><p>Commands can restrict which tools they use via the <code>allowed-tools</code> frontmatter:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Run the test suite</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowed-tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Bash, Read</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Run all tests and report results.</span></span></code></pre></div><p>Available tools: <code>Read</code>, <code>Write</code>, <code>Edit</code>, <code>Bash</code>, <code>Glob</code>, <code>Grep</code>, <code>WebFetch</code>, <code>Task</code></p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><code>~/.claude/commands/</code></td><td>User</td><td>Global commands</td></tr><tr><td><code>.claude/commands/</code></td><td>Project</td><td>Project-specific commands</td></tr></tbody></table><p>Commands are stored as <code>.md</code> files. Namespaces map to subdirectories: <code>tools:analyze</code> → <code>commands/tools/analyze.md</code>.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Plugin commands</strong> are read-only — you can view them but not edit or delete.</li><li><strong>Namespaces</strong> help organize large command libraries (e.g., <code>git:hooks</code>, <code>tools:lint</code>).</li><li>Use <strong>allowed-tools</strong> to restrict what a command can do for security.</li></ul>`,23)])])}const g=e(n,[["render",i]]);export{p as __pageData,g as default};
